INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox") VALUES(48,'the-monkey-boiz','The Monkey Boiz','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"                                                Monkey Boiz"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"                                         Start of fight dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Pygmy monkey: Well, you came to fight us. You must be dumb."},{"type":"hardBreak"},{"type":"text","text":"Orangutan: Yes indeed you are rather foolish."}]},{"type":"paragraph","content":[{"type":"text","text":"Gorrilla: Yea, yea dumb. Heh your really stupid."}]},{"type":"paragraph","content":[{"type":"text","text":"Pygmy monkey: Both of you, QUIET! As I was saying, why come up and fight us?"},{"type":"hardBreak"},{"type":"text","text":"Harper: By the looks of it, you have a token, and we would like it please."},{"type":"hardBreak"},{"type":"text","text":"Gorrilla: Scram turkey neck, or we squash you. We not nice apes."},{"type":"hardBreak"},{"type":"text","text":"Orangutan: Yes quite, please allow us to wallop you my good fellow."},{"type":"hardBreak"},{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"End of fight dialogue"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Pygmy monkey: Ouch! Ok ok, we have had enough. Take the token."}]},{"type":"paragraph","content":[{"type":"text","text":"Pygmy monkey: Please just leave. . ."}]},{"type":"paragraph","content":[{"type":"text","text":"Gorrilla: Waaa, my head hurts boss."},{"type":"hardBreak"},{"type":"text","text":"Orangutan: You big baby, don''t have a cry over it mate."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"~Fight Mechanics~"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"Pygmy Monkey"}]},{"type":"paragraph","content":[{"type":"text","text":"Pygmy monkey: Throws oranges in a fast flying simple predictive pattern."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"},{"type":"hardBreak"},{"type":"text","text":"Gorilla Monkey"}]},{"type":"paragraph","content":[{"type":"text","text":"Gorilla: fires coconuts in standard fire shot pattern, however when the coconuts hit the ground they launch towards the player as if they were rolling on the ground only on the X and Y axis."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"},{"type":"hardBreak"},{"type":"text","text":"Orangutan Monkey"}]},{"type":"paragraph","content":[{"type":"text","text":"Orangeutan: Shot pattern is a simple banana that launches towards the player which the player can continue to take damage from the banana as it is like acid on the floor."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:29:05','2026-08-03 03:59:55','                                                Monkey Boiz                                          Start of fight dialogue Pygmy monkey: Well, you came to fight us. You must be dumb. Orangutan: Yes indeed you are rather foolish. Gorrilla: Yea, yea dumb. Heh your really stupid. Pygmy monkey: Both of you, QUIET! As I was saying, why come up and fight us? Harper: By the looks of it, you have a token, and we would like it please. Gorrilla: Scram turkey neck, or we squash you. We not nice apes. Orangutan: Yes quite, please allow us to wallop you my good fellow. _________________________________________________________________________________ End of fight dialogue Pygmy monkey: Ouch! Ok ok, we have had enough. Take the token. Pygmy monkey: Please just leave. . . Gorrilla: Waaa, my head hurts boss. Orangutan: You big baby, don''t have a cry over it mate. _________________________________________________________________________________ ~Fight Mechanics~ Pygmy Monkey Pygmy monkey: Throws oranges in a fast flying simple predictive pattern. _________________________________________________________________________________ Gorilla Monkey Gorilla: fires coconuts in standard fire shot pattern, however when the coconuts hit the ground they launch towards the player as if they were rolling on the ground only on the X and Y axis. _________________________________________________________________________________ Orangutan Monkey Orangeutan: Shot pattern is a simple banana that launches towards the player which the player can continue to take damage from the banana as it is like acid on the floor.','{"image":"7c879567-2852-4e8a-9cb4-c6de0900a854.png","rows":[]}');
